import { LoadingSpinner } from "@mendix/ide-ui-components/progress/LoadingSpinner";
import React from "react";

export const CenteredLoadingSpinner: React.FC = () => {
    const containerStyle: React.CSSProperties = {
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        height: "100vh",
        width: "100%",
    };

    return (
        <div style={containerStyle} data-testid="loading-spinner">
            <LoadingSpinner />
        </div>
    );
};
